 pub fn close_demand(&self)->Result<RetirementDemand,ValueError>{if !self.birth.terminal_is_empty(){return self.birth.return_demand()}if self.returned.is_some(){return Ok(RetirementDemand{copy_bytes:size_of::<Option<(A,())>>()+size_of::<Option<A>>(),depth:1,..Default::default()})}match self.admission.as_deref(){None=>Ok(Default::default()),Some(admission)if admission.terminal_is_empty()=>self.next_demand(),Some(admission)if admission.phase()=="ready"=>Ok(admission.take_output_demand()),Some(admission)=>admission.next_return_demand()}}
