 pub fn new(input:A)->Self{Self{input:ManuallyDrop::new(Some(input)),backing:None,initialized:0,placed:false,work:None}}
 fn fixed(copy_bytes:usize,capacity_bytes:usize,release_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,capacity_bytes,release_bytes,depth:1}}
